// TRAY-ENGINE: the tray icon frames (apps/desktop/assets/tray, generated by build/tray-frames.mjs and
// packaged to <resources>/assets/tray by build/lib/tray-assets.mjs). Reads manifest.json strictly,
// maps frame ids to images per platform, and falls back: missing frame -> the static variant the
// engine settles on -> the built-in image. macOS: Template PNGs (Electron picks the @2x file next to
// it). Windows: the dark or light taskbar set, 16 px at 1x and 32 px at 2x.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { TrayAnimation, TraySequence, TraySequences } from './tray-engine.js';

/** Where the frames live under process.resourcesPath. */
export const TRAY_FRAMES_DIR = Object.freeze(['assets', 'tray']) as readonly string[];

export function trayFramesDir(resourcesPath: string): string {
  return join(resourcesPath, ...TRAY_FRAMES_DIR);
}

export type TaskbarTheme = 'dark' | 'light';

export interface TrayFrameFiles {
  readonly id: string;
  /** [1x, 2x] Template PNGs, relative to the tray folder. */
  readonly macos: readonly string[];
  /** Per taskbar colour, one PNG per `sizes.windows` entry (smallest first). */
  readonly windows: { readonly dark: readonly string[]; readonly light: readonly string[] };
}

export interface TrayManifest {
  readonly frames: ReadonlyMap<string, TrayFrameFiles>;
  readonly sequences: ReadonlyMap<string, TraySequence>;
  readonly windowsSizes: readonly number[];
}

/** The image subset of Electron's NativeImage the frames need. */
export interface TrayImage {
  isEmpty(): boolean;
  setTemplateImage(template: boolean): void;
  addRepresentation?(options: { scaleFactor: number; buffer: Uint8Array }): void;
}

export interface TrayImageModule {
  createFromPath(path: string): TrayImage;
  createFromBuffer(buffer: Uint8Array, options?: { scaleFactor?: number }): TrayImage;
}

const ANIMATIONS: readonly TrayAnimation[] = ['msg-in', 'msg-out', 'approval', 'connecting'];
// A relative path inside the tray folder: one known sub-folder, a plain file name, .png.
const SAFE_PATH = /^(macos|windows)\/[A-Za-z0-9][A-Za-z0-9_-]*(@2x)?\.png$/;
const SAFE_ID = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MAX_FRAMES = 256;

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

function fail(what: string): never {
  throw new Error(`Invalid tray manifest: ${what}.`);
}

function paths(v: unknown, what: string): readonly string[] {
  if (!Array.isArray(v) || v.length === 0 || v.length > 8) fail(what);
  for (const p of v) if (typeof p !== 'string' || !SAFE_PATH.test(p)) fail(what);
  return Object.freeze([...(v as string[])]);
}

function frameMs(v: unknown, fallback: number): number {
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < 16 || v > 1000) fail('frameMs');
  return v;
}

/** Validates manifest.json (as parsed JSON). Throws on any unexpected shape or path. */
export function parseTrayManifest(json: unknown): TrayManifest {
  if (!isRecord(json) || !isRecord(json.sequences)) fail('no sequences');
  const baseMs = frameMs(json.frameMs, 40);
  let windowsSizes: readonly number[] = [16, 32];
  if (json.sizes !== undefined) {
    if (!isRecord(json.sizes) || !Array.isArray(json.sizes.windows)) fail('sizes');
    const sizes = json.sizes.windows as unknown[];
    if (
      sizes.length === 0 ||
      sizes.some((s) => typeof s !== 'number' || !Number.isInteger(s) || s < 16 || s > 256)
    ) {
      fail('sizes');
    }
    windowsSizes = Object.freeze([...(sizes as number[])]);
  }
  const frames = new Map<string, TrayFrameFiles>();
  const sequences = new Map<string, TraySequence>();
  for (const [name, raw] of Object.entries(json.sequences)) {
    if (!SAFE_ID.test(name) || !isRecord(raw)) fail(`sequence ${name}`);
    if (
      typeof raw.loop !== 'boolean' ||
      !Array.isArray(raw.frames) ||
      raw.frames.length > MAX_FRAMES
    ) {
      fail(`sequence ${name}`);
    }
    const ids: string[] = [];
    for (const f of raw.frames as unknown[]) {
      if (!isRecord(f) || typeof f.id !== 'string' || !SAFE_ID.test(f.id))
        fail(`a frame in ${name}`);
      if (!isRecord(f.windows)) fail(`frame ${f.id}`);
      const files: TrayFrameFiles = Object.freeze({
        id: f.id,
        macos: paths(f.macos, `frame ${f.id} macos`),
        windows: Object.freeze({
          dark: paths(f.windows.dark, `frame ${f.id} windows dark`),
          light: paths(f.windows.light, `frame ${f.id} windows light`),
        }),
      });
      frames.set(f.id, files);
      ids.push(f.id);
    }
    sequences.set(
      name,
      Object.freeze({
        frames: Object.freeze(ids),
        frameMs: frameMs(raw.frameMs, baseMs),
        loop: raw.loop,
      }),
    );
  }
  return { frames, sequences, windowsSizes };
}

/** The sequences the engine plays; a missing one is empty (the engine then settles at once). */
export function engineSequences(manifest: TrayManifest): TraySequences {
  const out = {} as Record<TrayAnimation, TraySequence>;
  for (const name of ANIMATIONS) {
    out[name] = manifest.sequences.get(name) ?? {
      frames: [],
      frameMs: 40,
      loop: name === 'connecting',
    };
  }
  return Object.freeze(out);
}

export interface TrayFramesOptions {
  readonly manifest: TrayManifest;
  /** The tray folder (trayFramesDir(process.resourcesPath) when packaged). */
  readonly dir: string;
  readonly platform: string;
  readonly nativeImage: TrayImageModule;
  /** The last fallback: the built-in image (tray.ts BUILTIN_TRAY_PNG). */
  readonly fallback: () => TrayImage;
  readonly readFile?: (path: string) => Uint8Array;
}

export class TrayFrames {
  readonly sequences: TraySequences;
  readonly #o: TrayFramesOptions;
  readonly #readFile: (path: string) => Uint8Array;
  readonly #cache = new Map<string, TrayImage | null>();
  #builtin: TrayImage | null = null;

  constructor(options: TrayFramesOptions) {
    this.#o = options;
    this.#readFile = options.readFile ?? ((p) => readFileSync(p));
    this.sequences = engineSequences(options.manifest);
  }

  get isMac(): boolean {
    return this.#o.platform === 'darwin';
  }

  /** The image for a frame: the frame, else the settle frame, else the built-in image. Never throws. */
  image(id: string, settle: string, theme: TaskbarTheme): TrayImage {
    const img = this.#load(id, theme) ?? this.#load(settle, theme);
    if (img !== null) return img;
    if (this.#builtin === null) {
      this.#builtin = this.#o.fallback();
      if (this.isMac) this.#builtin.setTemplateImage(true);
    }
    return this.#builtin;
  }

  #load(id: string, theme: TaskbarTheme): TrayImage | null {
    const key = this.isMac ? id : `${theme}:${id}`;
    const cached = this.#cache.get(key);
    if (cached !== undefined) return cached;
    let img: TrayImage | null;
    try {
      img = this.#create(id, theme);
    } catch {
      img = null;
    }
    if (img !== null && img.isEmpty()) img = null;
    this.#cache.set(key, img);
    return img;
  }

  #create(id: string, theme: TaskbarTheme): TrayImage | null {
    const files = this.#o.manifest.frames.get(id);
    if (files === undefined) return null;
    const { dir, nativeImage } = this.#o;
    if (this.isMac) {
      const first = files.macos[0];
      if (first === undefined) return null;
      const img = nativeImage.createFromPath(join(dir, first));
      img.setTemplateImage(true);
      return img;
    }
    const set = files.windows[theme];
    const sizes = this.#o.manifest.windowsSizes;
    const base = sizes[0] ?? 16;
    const first = set[0];
    if (first === undefined) return null;
    const img = nativeImage.createFromBuffer(this.#readFile(join(dir, first)), { scaleFactor: 1 });
    if (img.isEmpty()) return null;
    set.slice(1).forEach((file, i) => {
      const size = sizes[i + 1];
      if (size === undefined || img.addRepresentation === undefined) return;
      img.addRepresentation({ scaleFactor: size / base, buffer: this.#readFile(join(dir, file)) });
    });
    img.setTemplateImage(false);
    return img;
  }
}

export type LoadTrayFramesOptions = Omit<TrayFramesOptions, 'manifest'>;

/** Reads <dir>/manifest.json; null when it is missing or invalid (the tray then uses one image). */
export function loadTrayFrames(options: LoadTrayFramesOptions): TrayFrames | null {
  const read = options.readFile ?? ((p: string) => readFileSync(p));
  try {
    const text = new TextDecoder('utf-8', { fatal: true }).decode(
      read(join(options.dir, 'manifest.json')),
    );
    return new TrayFrames({ ...options, manifest: parseTrayManifest(JSON.parse(text)) });
  } catch {
    return null;
  }
}
